from itertools import product
from typing import Callable, Dict, Optional, Tuple

State = int

def affine_perm(a: int, c: int, n: int) -> Callable[[State], State]:
    return lambda x: (a * x + c) % n

def claw_compress(g0, g1):
    return lambda s, b: g1(s) if b else g0(s)

def find_claw(g0, g1, dom) -> Optional[Tuple[int, int]]:
    return next(((x, y) for x in dom for y in dom if g0(x) == g1(y)), None)

def find_compression_collision(f, dom):
    seen: Dict[int, Tuple[int, bool]] = {}
    for s, b in product(dom, (False, True)):
        out = f(s, b)
        if out in seen and seen[out] != (s, b):
            return seen[out], (s, b)
        seen.setdefault(out, (s, b))
    return None

def demonstrate_collision_equals_claw(n: int = 7) -> None:
    """Exercises claw_iff_compression_collision on affine permutations mod n:
    finds a claw, finds a compression collision, and shows each yields the
    other (both directions of the equivalence)."""
    g0, g1 = affine_perm(2, 1, n), affine_perm(3, 5, n)
    dom = list(range(n))
    f = claw_compress(g0, g1)
    claw = find_claw(g0, g1, dom)
    coll = find_compression_collision(f, dom)
    x, y = claw
    assert f(x, False) == f(y, True)            # claw -> collision
    (s, b), (s2, b2) = coll                      # collision -> claw
    recovered = (s, s2) if (not b and b2) else (s2, s)
    assert g0(recovered[0]) == g1(recovered[1])
    print(f"n={n}: claw {claw} <=> collision {coll}; recovered claw {recovered}")

if __name__ == "__main__":
    for n in (5, 7, 11):
        demonstrate_collision_equals_claw(n)

from itertools import product
from typing import Callable, Dict, List, Optional, Tuple

State = int

def affine_perm(a: int, c: int, n: int) -> Callable[[State], State]:
    return lambda x: (a * x + c) % n

def claw_compress(g0, g1):
    return lambda s, b: g1(s) if b else g0(s)

def md_hash(f, iv: State, msg: List[bool]) -> State:
    s = iv
    for b in msg:
        s = f(s, b)
    return s

def demonstrate_headline_reduction(n: int = 7, iv: State = 0) -> None:
    """Exercises clawFree_mdHash_injOn_length / md_clawCompress_collision_to_claw:
    finds two equal-length messages with the same iterated hash, extracts the
    compression collision, and converts it to a claw of the permutation pair."""
    g0, g1 = affine_perm(2, 1, n), affine_perm(3, 5, n)
    f = claw_compress(g0, g1)
    found: Optional[Tuple[List[bool], List[bool]]] = None
    for L in range(1, 6):
        seen: Dict[State, List[bool]] = {}
        for bits in product((False, True), repeat=L):
            msg = list(bits)
            h = md_hash(f, iv, msg)
            if h in seen and seen[h] != msg:
                found = (seen[h], msg); break
            seen.setdefault(h, msg)
        if found:
            break
    assert found is not None
    m1, m2 = found
    # extract (Algorithm A)
    a, b = list(m1), list(m2)
    while True:
        in1 = (md_hash(f, iv, a[:-1]), a[-1])
        in2 = (md_hash(f, iv, b[:-1]), b[-1])
        if in1 != in2:
            break
        a, b = a[:-1], b[:-1]
    # to claw (Algorithm B)
    (s, bit), (s2, bit2) = in1, in2
    claw = (s, s2) if (not bit and bit2) else (s2, s)
    assert g0(claw[0]) == g1(claw[1])
    print(f"n={n}: collision {[int(x) for x in m1]} vs {[int(x) for x in m2]} "
          f"-> claw {claw}, g0={g0(claw[0])}=g1={g1(claw[1])}")

if __name__ == "__main__":
    for n in (5, 7, 11):
        demonstrate_headline_reduction(n)

from itertools import product
from typing import Callable, Dict, Optional, Tuple

State = int

def find_compression_collision(f, dom):
    seen: Dict[int, Tuple[int, bool]] = {}
    for s, b in product(dom, (False, True)):
        out = f(s, b)
        if out in seen and seen[out] != (s, b):
            return seen[out], (s, b)
        seen.setdefault(out, (s, b))
    return None

def demonstrate_pigeonhole_inevitability(n: int = 5) -> None:
    """Exercises compression_collision_of_card: over a finite state space with
    two block values, EVERY compression function has a collision. We verify it
    for a battery of unrelated compression functions."""
    dom = list(range(n))
    funcs: Dict[str, Callable[[int, bool], int]] = {
        "(s*s+3b) mod n": lambda s, b: (s * s + 3 * int(b)) % n,
        "(2s+b) mod n":   lambda s, b: (2 * s + int(b)) % n,
        "(s^b) mod n":    lambda s, b: (s ^ int(b)) % n,
    }
    for name, f in funcs.items():
        coll = find_compression_collision(f, dom)
        assert coll is not None
        print(f"{name:16s}: collision {coll}")

if __name__ == "__main__":
    demonstrate_pigeonhole_inevitability(5)
    demonstrate_pigeonhole_inevitability(8)

